//
let t =
baseTransactions
| where timestamp between (_startTime .. _endTime)
;
//
// Get POS Mapping table for possible filtering
//
let posMapping = pos_mapping
  | where user_telemetry_id has_any (param_userTelemetryId)
  | where pos_name has_any (param_posName)
  | where pos_terminal_no has_any (param_posTerminalNo)
;
//
// 1) Latest event per TransactionKey (for "current status" + last event details)
//
let latestPerTxn =
t
| summarize
    arg_max(timestamp,
            eventId, message, Stage, Result, StoreNo, POSTerminalNo, TransactionNo, TableNo, FailureReason,
            alUserId, alSessionId, environmentName, environmentType
    ) by TransactionKey;
//
// 2) Last sent time per TransactionKey
//
let lastSentPerTxn =
  t
  | where Stage == 'Enqueued'
  | where Result == 'Success'
  | summarize LastSentTime = max(timestamp) by TransactionKey
;
//
// 3) Last error time (and optionally last error text) per TransactionKey
//
let lastErrorPerTxn =
  t
  | where Result == 'Error'
  | summarize
    LastErrorTime = max(timestamp),
    LastFailureReason = arg_max(timestamp, FailureReason).FailureReason
    by TransactionKey
;
//
latestPerTxn
| join kind=leftouter lastSentPerTxn on TransactionKey
| join kind=leftouter lastErrorPerTxn on TransactionKey
| join kind=inner (
    posMapping
    | project pos_terminal_no, user_telemetry_id, pos_name  // Keep only needed fields
)
// on $left.usertelemetryId == $right.user_telemetry_id
on $left.POSTerminalNo == $right.pos_terminal_no
| extend TransactionStatus = case(
    (Stage == 'Posted'), "Transaction has been posted in POS but not yet sent to Service Bus/Azure Storage",
    (Stage == 'Enqueued' and Result == 'Error'), "Transaction has not been sent to Service Bus/Azure Storage due to an error",
    (Stage == 'Enqueued' and Result == 'Success'), "Transaction has been successfully sent to Service Bus/Azure Storage",
    (Stage == 'Applied' and Result == 'Error'), "Transaction has been posted in POS and sent to Service Bus/Azure Storage but failed to be applied in Headoffice",
    (Stage == 'Applied' and Result == 'Success'), "Transaction has been successfully applied in Headoffice",
    "Unknown status"
)
| project
    timestamp,                  // last event timestamp
    Stage,
    Result,
    TransactionNo,
    StoreNo,
    POSTerminalNo,
    TransactionStatus,
    FailureReason,                  // error text on the *last event* (if last event is 0003)
    eventId,                    // last event id
    LastSentTime,
    LastErrorTime,
    LastFailureReason,
    message,
    TransactionKey,
    alUserId,
    alSessionId,
    TableNo
| sort by timestamp desc

let t = 
baseTransactions
| order by timestamp desc
;
//
// Step 1: Get all events
//
let allEvents = t;
//
// Step 2: Join the POSes list with the events
//
pos_mapping
| where user_telemetry_id has_any (param_userTelemetryId)
| where pos_name has_any (param_posName)
| where pos_terminal_no has_any (param_posTerminalNo)
| join kind=leftouter (
    allEvents
)
// on $left.user_telemetry_id == $right.userTelemetryId
on $left.pos_terminal_no == $right.POSTerminalNo
| summarize LatestTimestamp = max(timestamp) by pos_terminal_no, pos_name, user_telemetry_id
| project 
    posTerminalNo = pos_terminal_no,
    posName = pos_name, 
    userTelemetryId = user_telemetry_id,
    latestTimestamp = coalesce(format_datetime(LatestTimestamp, 'yyyy-MM-dd HH:mm:ss'), "N/A")

let t = 
  baseTransactions
  | where timestamp >= ago(1h)
  | where userTelemetryId has_any (param_userTelemetryId)
;
//
let posMapping = pos_mapping
| where user_telemetry_id has_any (param_userTelemetryId)
| where pos_name has_any (param_posName)
| where pos_terminal_no has_any (param_posTerminalNo);
//
t
| join kind=inner (
    posMapping
    | project pos_terminal_no, user_telemetry_id, pos_name
) on $left.POSTerminalNo == $right.pos_terminal_no
| count
| project ["Errors in Last 1h"] = Count

let t = 
  baseTransactions
  | where timestamp >= ago(8h)
  | where userTelemetryId has_any (param_userTelemetryId)
;
//
let posMapping =
  pos_mapping
  | where user_telemetry_id has_any (param_userTelemetryId)
  | where pos_name has_any (param_posName)
  | where pos_terminal_no has_any (param_posTerminalNo);
//
t
  | join kind=inner (
      posMapping
      | project pos_terminal_no, user_telemetry_id, pos_name
  ) on $left.POSTerminalNo == $right.pos_terminal_no
  | count
  | project ["Errors in Last 8h"] = Count
;

let trans_replic_eventId = 'AL10012870';

let t =
    baseTransactions
    | where timestamp between (_startTime .. _endTime)
    | project timestamp, eventId, Stage, Result, TransactionKey, TransactionNo, POSTerminalNo
;
//
// Step 1: Get the latest finish event per TransactionKey
//
let finishedEvents =
t
| where eventId == trans_replic_eventId
    and Stage == 'Applied'
    and Result == 'Success'
| summarize MaxFinishTime = max(timestamp) by TransactionKey;
//
// Step 2: Get all error events
//
let errorEvents = t
| where Result == 'Error'
;
//
// Get POS Mapping table for possible filtering
//
let posTerminals =
    pos_mapping
    | where user_telemetry_id has_any (param_userTelemetryId)
    | where pos_name has_any (param_posName)
    | where pos_terminal_no has_any (param_posTerminalNo)
    | project pos_terminal_no
;

//
// Step 4: Join filtered errorEvents with posMapping to allow pos_name filtering
//
errorEvents
| where eventId == trans_replic_eventId
| join kind=leftanti finishedEvents on TransactionKey
// | join kind=leftouter finished on TransactionKey
// | where isnull(MaxFinishTime) or timestamp > MaxFinishTime
| where POSTerminalNo in (posTerminals)
| summarize ErrorEvents = count()

let aggregationInterval = totimespan(param_aggregationInterval);
let posName = param_posName;
//
let t = 
baseTransactions
| where userTelemetryId has_any (param_userTelemetryId)
;
// Get POS Mapping table for filtering
let posMapping = pos_mapping
	| where user_telemetry_id has_any (param_userTelemetryId)
	| where pos_name has_any (param_posName)
	| where pos_terminal_no has_any (param_posTerminalNo)
;
//
t
| join kind=inner (
    posMapping
    | project pos_terminal_no, user_telemetry_id, pos_name  // Keep only needed fields
)
// on $left.userTelemetryId == $right.user_telemetry_id
on $left.POSTerminalNo == $right.pos_terminal_no
| summarize count() by bin(timestamp, aggregationInterval), POSTerminalNo
| render columnchart

let aggregationInterval = totimespan(param_aggregationInterval);
//
let TimeBins = range timestamp from _startTime to _endTime step aggregationInterval;
	let t = 
    baseTransactions
    | where userTelemetryId has_any (param_userTelemetryId)
;
//
// Get POS Mapping table for filtering
let posMapping = pos_mapping
| where user_telemetry_id has_any (param_userTelemetryId)
| where pos_name has_any (param_posName)
| where pos_terminal_no has_any (param_posTerminalNo)
;
//
let eventCount =
  t
  | join kind=inner (
      posMapping
      | project pos_terminal_no, user_telemetry_id, pos_name  // Keep only needed fields
  )
  // on $left.userTelemetryId == $right.user_telemetry_id
  on $left.POSTerminalNo == $right.pos_terminal_no
  | summarize count_ = count() by bin(timestamp, aggregationInterval), userTelemetryId, pos_terminal_no;

// Outer join to include all time bins even with 0 events
TimeBins
| extend timestamp = bin(timestamp, aggregationInterval)  // Ensure bin alignment
| join kind=leftouter eventCount on timestamp
| project timestamp
// , userTelemetryId = coalesce(userTelemetryId, "N/A"), eventCount = coalesce(count_, 0)
, pos_terminal_no = coalesce(pos_terminal_no, "N/A"), eventCount = coalesce(count_, 0)
// , pos_terminal_no
| render columnchart

// Store/POS Terminal No. from telemetry events
let t =
    baseTransactions
    | where StoreNo <> '' and POSTerminalNo <> ''
    | summarize by StoreNo, POSTerminalNo;

// Store/POS Terminal No. from POS mapping table
let mapped_pos =
    pos_mapping
    | project StoreNo = tostring(store_no), POSTerminalNo = tostring(pos_terminal_no);

mapped_pos
| join kind=leftanti t on StoreNo, POSTerminalNo
| project StoreNo, POSTerminalNo

// Store/POS Terminal No. from telemetry events
let t =
    baseTransactions
    | where StoreNo <> '' and POSTerminalNo <> ''
    | summarize by StoreNo, POSTerminalNo
;

// Store/POS Terminal No. from POS mapping table
let mapped_pos =
    pos_mapping
    | project StoreNo = tostring(store_no), POSTerminalNo = tostring(pos_terminal_no)
;

t
| join kind=leftanti mapped_pos on StoreNo, POSTerminalNo
| project StoreNo, POSTerminalNo
;

