// datatable(store_no: string, pos_terminal_no: string, user_telemetry_id: string, pos_name: string)
// [
//   "HO", "HO", "user_from_HO", "HO",
//   "S0001", "P0001", "user_from_pos1", "POS1",
//   "S0001", "P0002", "user_from_pos2", "POS2",
//   "S0001", "P0003", "user_from_pos3", "POS3"
// ]
//
let csvUrl = "{CSV_URL_WITH_SAS}";
externaldata(store_no: string, pos_terminal_no: string, user_telemetry_id: string, pos_name: string)
[
  csvUrl
]
with (format="csv", ignoreFirstRecord=true)
| sort by store_no, pos_terminal_no asc
